import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"訟","description":"周易集解 - 訟","frontmatter":{"title":"訟","description":"周易集解 - 訟"},"headers":[],"relativePath":"zh/classics/jijie/006.md","filePath":"zh/classics/jijie/006.md"}'),l={name:"zh/classics/jijie/006.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="訟" tabindex="-1">訟 <a class="header-anchor" href="#訟" aria-label="Permalink to “訟”">​</a></h1><h2 id="訟-1" tabindex="-1">訟 <a class="header-anchor" href="#訟-1" aria-label="Permalink to “訟”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>訟，有孚，窒惕，中吉，終凶。利見大人，不利涉大川。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：飲食必有訟，故受之以訟也。</p><p>鄭玄曰：訟，猶爭也，言飲食之會恆多爭也。</p><p>乾寶曰：訟，離之游魂也。離為戈兵，此天氣將刑殺，聖人將用師之卦也。訟，不親也。兆民未識天命不同之意。</p><p>荀爽曰：陽來居二，而孚於初，故曰訟有孚矣。</p><p>虞翻曰：遯三之二也。孚謂二。窒，塞止也。惕，懼二也。二失位，故不言貞。遯將成否，則子弒父，臣弒君。三來之二，得中，弒不得行，故中吉也。</p><p>虞翻曰：二失位，終止不變，則入於淵，故終凶也。</p><p>侯果曰：大人，謂五也。斷決必中，故利見也。訟是陰事，以險涉險，故不利涉大川。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：訟，上剛下險，險而健，訟。訟，有孚窒惕，中吉，剛來而得中也。終凶，訟不可成也。利見大人，尚中正也。不利涉大川，入於淵也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>盧氏曰：險而健者，恆好爭訟也。</p><p>蜀才曰：此本遯卦。</p><p>案：二進居三，三降居二，是剛來而得中也。</p><p>王肅曰：以訟成功者，終必凶也。</p><p>王弼曰：凡不和而訟，無施而可，涉難特甚焉。唯有信而見塞懼者，乃可以得吉也。猶復不可以終，中乃吉也。不閉其源，使訟不至，雖每不枉，而訟至終竟，此亦凶矣。故雖復有信，而見塞懼，猶不可以為終，故曰「訟，有孚窒惕，中吉終凶」也。無善聽者，雖有其實，何由得明。而令有信塞懼者，得其中吉，必有善聽之主焉。其在二乎？以剛而來，正夫群小，斷不失中，應其任矣。</p><p>案：天為訟，善聽之主者，其在五焉。何以明之？案爻辭九五「訟元吉」王氏註雲「處得尊位，為訟之主，用其中正，以斷枉直」，即《彖》雲「利見大人，尚中正」，是其義也。九二《象》曰「不克訟，歸逋竄也。自下訟上，患至掇也」。九二居訟之時，自救不暇，訟既不克，懷懼逃歸，僅得免其終凶禍，豈能為善聽之主哉。年代綿流，師資道喪，恐傳寫字誤，以五為二，後賢當審詳之也。</p><p>荀爽曰：二與四訟，利見於五。五以中正之道，解其訟也。</p><p>荀爽曰：陽來居二，坎在下為淵。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：天與水違行，訟。君子以作事謀始。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：天自西轉，水自東流，上下違行，成訟之象也。</p><p>虞翻曰：君子謂乾。三來變坤，為作事。坎為謀。乾知大始。故以作事謀始。</p><p>乾寶曰：省民之情，以製作也。武王故先觀兵孟津，蓋以卜天下之心，故曰作事謀始也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，不永所事，小有言，終吉。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：永，長也。坤為事，初失位，而為訟始，故不永所事也。小有言，謂初四易位成震，言三食舊德，震象半見，故小有言。初變得正，故終吉也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不永所事，訟不可長也。雖小有言，其辯明也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>盧氏曰：初欲應四，而二據之。蹔爭，事不至永。雖有小訟，訟必辯明，故終吉。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，不克訟，歸而逋。其邑人三百戶，無眚。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：謂與四訟，坎為隱伏，故逋。乾位剛在上，坎濡失正，故不克也。</p><p>虞翻曰：眚，災也，坎為眚，謂二變應五。乾為百，坤為戶。三爻，故三百戶。坎化為坤，故無眚。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不克訟，歸逋竄也。自下訟上，患至掇也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：三不克訟，故逋而歸。坤稱邑。二者，邑中之陽人。逋，逃也，謂逃失邑中之陽人。</p><p>荀爽曰：下與上爭，即取患害，如拾掇小物而不失也。坤有三爻，故雲「三百戶，無眚」。二者，下體之君。君不爭，則百姓無害也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，食舊德，貞厲，終吉。或從王事，無成。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：乾為舊德。食謂初。四二已變之正。三動得位，體噬嗑食。四變食乾，故食舊德。三變在坎，正危貞厲，得位，故終吉也。</p><p>虞翻曰：乾為王。二變否時，坤為事，故或從王事。道無成而代有終，故曰無成。坤三同義也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：食舊德，從上吉也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：雖失其位，專心應上，故能保全舊恩，食舊德者也。處兩剛之間，而皆近不相得。乘二負四，正之危也。剛不能侵，故終吉也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，不克訟，復即命渝，安貞吉。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：失位，故不克訟。渝變也。不克訟，故複位。變而成巽，巽為命令，故復即命渝。動而得位，故安貞吉。謂二已變坤安也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：復即命渝，安貞吉，不失也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：初既辯明，四訟妄也。訟既不克，當反就前理，變其詔命，則安靜貞吉而不失初也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，訟，元吉。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：訟元吉，以中正也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>王肅曰：以中正之德，齊乖爭之俗，元吉也。</p><p>王弼曰：處得尊位，為訟之主。用其中正，以斷枉直。中則不過，正則不邪，剛則無所溺，公則無所偏。故訟元吉。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，或錫之鞶帶，終朝三褫之。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：錫謂王之錫命。鞶帶，大帶。男子鞶革。初四已易位，三二之正，巽為腰帶，故鞶帶。</p><p>虞翻曰：位終乾上。二變時，坤為終。離為日，乾為甲。日出甲上，故稱朝。應在三，三變時，艮為手，故終朝三褫之。使變應已，則去其鞶帶。體坎乘陽，故象曰不足敬也。</p><p>荀爽曰：二四爭三，三本下體，取之有緣。或者，疑之辭也。以三錫二，於義疑矣。爭競之世，分理未明，故或以錫二。終朝者，君道明。三者，陽成功也。君明道盛，則奪二與四，故曰終朝三褫之也。鞶帶，宗廟之服。三應於上，上為宗廟。故曰鞶帶也。</p><p>翟玄曰：上以六三錫下三陽，群剛交爭，得不以讓，故終一朝之間，各一奪之，為三褫。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：以訟受服，亦不足敬也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：服謂鞶帶。終朝見褫，乾象毀壞。故不足敬。</p><p>《九家易》曰：初、二、三、四皆不正，以不正相訟，而得其服，故不足敬也。</p>',83)])])}const m=e(l,[["render",p]]);export{b as __pageData,m as default};
